using PC28168.U20241G031.OpenPay.Platform.Settlements.Domain.Model.Commands;
using PC28168.U20241G031.OpenPay.Platform.Settlements.Domain.Model.ValueObjects;
using PC28168.U20241G031.OpenPay.Platform.Shared.Domain.Model.ValueObjects;

namespace PC28168.U20241G031.Openpay.Platform.Settlements.Domain.Model.Aggregates;

/// <summary>
/// DisbursementOrder aggregate root for managing fund liquidation and transfer operations in Openpay.
/// </summary>
/// <remarks>Piero Francisco Montes Chang</remarks>
public partial class DisbursementOrder
{
    /// <summary>
    /// Gets the autogenerated primary key identifier.
    /// </summary>
    public int Id { get; private set; }

    /// <summary>
    /// Gets the unique order tracking code value object.
    /// </summary>
    public OpenpayReference OrderTrackingCode { get; private set; }

    /// <summary>
    /// Gets the affiliate store identifier value object.
    /// </summary>
    public StoreIdentifier AffiliateStoreId { get; private set; }

    /// <summary>
    /// Gets the execution schedule date interval value object.
    /// </summary>
    public DateInterval ExecutionSchedule { get; private set; }

    /// <summary>
    /// Gets the transfer cap financial amount value object.
    /// </summary>
    public FinancialAmount TransferCap { get; private set; }

    /// <summary>
    /// Gets the disbursement order status.
    /// </summary>
    public DisbursementStatus Status { get; private set; }

    /// <summary>
    /// Gets the operator user identifier who registered the order (mandatory, max 20 chars).
    /// </summary>
    public string User { get; private set; }

    /// <summary>
    /// Gets the optional remarks of the disbursement order (optional, max 85 chars).
    /// </summary>
    public string? Remarks { get; private set; }

    /// <summary>
    /// Initializes a new instance of the <see cref="DisbursementOrder"/> class for EF Core materialization.
    /// </summary>
    protected DisbursementOrder()
    {
        OrderTrackingCode = null!;
        AffiliateStoreId = null!;
        ExecutionSchedule = null!;
        TransferCap = null!;
        User = string.Empty;
        Remarks = null;
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="DisbursementOrder"/> class from a <see cref="CreateDisbursementOrderCommand"/>.
    /// </summary>
    /// <param name="command">The command containing primitive attributes for the disbursement order.</param>
    /// <exception cref="ArgumentException">Thrown when any domain rule on identifiers, dates, status, user, or remarks is violated.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the transfer cap amount is negative.</exception>
    /// <exception cref="ArgumentNullException">Thrown when the transfer cap currency code is null or blank.</exception>
    /// <remarks>Piero Francisco Montes Chang</remarks>
    public DisbursementOrder(CreateDisbursementOrderCommand command)
    {
        // Instantiate Value Objects (Rules 2, 3, 4, 5, 7, 8)
        OrderTrackingCode = new OpenpayReference(command.OrderTrackingCode);
        AffiliateStoreId = new StoreIdentifier(command.AffiliateStoreId);
        ExecutionSchedule = new DateInterval(command.ScheduledFrom, command.ScheduledTo);
        TransferCap = new FinancialAmount(command.TransferCapAmount, command.TransferCapCurrencyCode);

        // Business Rule 11: User is mandatory (not null or empty) and must not exceed 20 characters.
        if (string.IsNullOrWhiteSpace(command.User))
        {
            throw new ArgumentException("User is mandatory and cannot be null or empty.", nameof(command));
        }

        var trimmedUser = command.User.Trim();
        if (trimmedUser.Length > 20)
        {
            throw new ArgumentException("User cannot exceed 20 characters in length.", nameof(command));
        }
        User = trimmedUser;

        // Business Rule 12: Remarks is optional, and if provided, must not exceed 85 characters.
        if (command.Remarks is not null)
        {
            if (command.Remarks.Length > 85)
            {
                throw new ArgumentException("Remarks cannot exceed 85 characters in length.", nameof(command));
            }
            Remarks = command.Remarks;
        }
        else
        {
            Remarks = null;
        }

        // Business Rule 10: DisbursementStatus starts at 10 (Queued = 10 default, Processed = 11, Cancelled = 12, Failed = 13).
        if (string.IsNullOrWhiteSpace(command.Status))
        {
            Status = DisbursementStatus.Queued;
        }
        else if (Enum.TryParse<DisbursementStatus>(command.Status.Trim(), ignoreCase: true, out var parsedStatus) &&
                 Enum.IsDefined(typeof(DisbursementStatus), parsedStatus))
        {
            Status = parsedStatus;
        }
        else
        {
            throw new ArgumentException(
                $"Invalid DisbursementStatus value: '{command.Status}'. Allowed values are Queued (10), Processed (11), Cancelled (12), or Failed (13).",
                nameof(command));
        }
    }
}